    logic                                        desc_axi_int_rlast;
    logic [AXI_ID_WIDTH-1:0]                     desc_axi_int_rid;

    //=========================================================================
    // Internal Signals - Monitor Bus Aggregation
    //=========================================================================

    // MonBus from descriptor AXI monitor (packet + side-band timestamp)
    logic                                       desc_axi_mon_valid;
    logic                                       desc_axi_mon_ready;
    ocelus_common_pkg::monitor_packet_t        desc_axi_mon_packet;
    ocelus_common_pkg::monbus_timestamp_t      desc_axi_mon_timestamp;

    // Shared engines' MonBus streams (driven only when SHARED_ENGINES != 0)
    logic                                       sh_desc_mon_valid,   sh_desc_mon_ready;
    ocelus_common_pkg::monitor_packet_t        sh_desc_mon_packet;
    ocelus_common_pkg::monbus_timestamp_t      sh_desc_mon_timestamp;
    logic                                       sh_ctrlrd_mon_valid, sh_ctrlrd_mon_ready;
    ocelus_common_pkg::monitor_packet_t        sh_ctrlrd_mon_packet;
    ocelus_common_pkg::monbus_timestamp_t      sh_ctrlrd_mon_timestamp;
    logic                                       sh_ctrlwr_mon_valid, sh_ctrlwr_mon_ready;
    ocelus_common_pkg::monitor_packet_t        sh_ctrlwr_mon_packet;
    ocelus_common_pkg::monbus_timestamp_t      sh_ctrlwr_mon_timestamp;

    // Combined MonBus arrays (9 sources: 8 channels + 1 desc AXI monitor)
    //   per-channel engines: one stream per scheduler_group + desc AXI monitor
    //   shared engines: one per scheduler + desc / ctrlrd / ctrlwr engines + monitor
    localparam int MONBUS_SOURCES = (SHARED_ENGINES != 0) ? NUM_CHANNELS + 4 : NUM_CHANNELS + 1;
    // Use unpacked arrays to match monbus_arbiter port types
    logic                                       monbus_valid_all     [MONBUS_SOURCES];
    logic                                       monbus_ready_all     [MONBUS_SOURCES];
    ocelus_common_pkg::monitor_packet_t        monbus_packet_all    [MONBUS_SOURCES];
    ocelus_common_pkg::monbus_timestamp_t      monbus_timestamp_all [MONBUS_SOURCES];

    initial begin
        // rapids-g: the schedulers are scheduler_g, which exist only in the
        // shared-engine structure; one gatling serves 4, 8 or 16 of them.
        if (SHARED_ENGINES == 0)
            $fatal(1, "scheduler_group_array_g: rapids-g needs SHARED_ENGINES = 1");
        if ((NUM_CHANNELS != 4) && (NUM_CHANNELS != 8) && (NUM_CHANNELS != 16))
            $fatal(1, "scheduler_group_array_g: NUM_CHANNELS must be 4, 8 or 16, got %0d", NUM_CHANNELS);
        if ((TILE_HDR != 0) && (SHARED_ENGINES == 0))
            $fatal(1, "TILE_HDR = 1 needs SHARED_ENGINES = 1 (the injection port is in descriptor_engine_shared)");
    end

    //=========================================================================
    // Beats Scheduler Group Array Instantiation
    //=========================================================================

    generate
    if (SHARED_ENGINES == 0) begin : g_per_channel
        // No tile header on the per-channel structure (its descriptor engines
        // have no second writer); TILE_HDR = 1 is refused below.
        assign sched_rd_pkt_tile = '0;
        assign desc_inj_dropped  = '0;
        assign desc_inj_ready    = 1'b1;
        logic unused_inj;
        assign unused_inj = &{1'b0, desc_inj_valid, desc_inj_ch, desc_inj_data, desc_inj_dropped_clr,
                              tile_adv_done, tile_dest_legal};
        for (genvar ch = 0; ch < NUM_CHANNELS; ch++) begin : gen_scheduler_groups
            scheduler_group #(
                .CHANNEL_ID             (ch),
                .NUM_CHANNELS           (NUM_CHANNELS),
                .CHAN_WIDTH             (CHAN_WIDTH),
                .ADDR_WIDTH             (ADDR_WIDTH),
                .DATA_WIDTH             (DATA_WIDTH),
                .AXI_ID_WIDTH           (AXI_ID_WIDTH),
                .DESC_MON_AGENT_ID      (16'(DESC_MON_BASE_AGENT_ID + ch)),
                .SCHED_MON_AGENT_ID     (16'(SCHED_MON_BASE_AGENT_ID + ch)),
                .CTRLRD_MON_AGENT_ID    (16'(32 + ch)),   // 0x20.. per channel
                .CTRLWR_MON_AGENT_ID    (16'(40 + ch)),   // 0x28.. per channel
                .MON_UNIT_ID            (8'(MON_UNIT_ID)),
                .MON_CHANNEL_ID         (9'(ch)),
                .EN_READ                (EN_READ),
                .EN_WRITE               (EN_WRITE),
                .GEN_MON                (GEN_MON),
                .USE_ROW_COL_MAJOR_ADDRESSING (USE_ROW_COL_MAJOR_ADDRESSING)
            ) u_scheduler_group (
                .clk                    (clk),
                .rst_n                  (rst_n),

                // APB interface
                .apb_valid              (apb_valid[ch]),
                .apb_ready              (apb_ready[ch]),
                .apb_addr               (apb_addr[ch]),

                // Configuration
                .cfg_channel_enable     (cfg_channel_enable[ch]),
                .cfg_channel_reset      (cfg_channel_reset[ch]),

                // Scheduler Configuration (global)
                .cfg_sched_timeout_cycles   (cfg_sched_timeout_cycles),
                .cfg_sched_timeout_limit    (cfg_sched_timeout_limit),
                .cfg_sched_timeout_enable   (cfg_sched_timeout_enable),
                .cfg_sched_err_enable       (cfg_sched_err_enable),
                .cfg_sched_compl_enable     (cfg_sched_compl_enable),
                .cfg_sched_perf_enable      (cfg_sched_perf_enable),

                // Descriptor Engine Configuration (global)
                .cfg_desceng_prefetch       (cfg_desceng_prefetch),
                .cfg_desceng_fifo_thresh    (cfg_desceng_fifo_thresh),
                .cfg_desceng_addr0_base     (cfg_desceng_addr0_base),
                .cfg_desceng_addr0_limit    (cfg_desceng_addr0_limit),
                .cfg_desceng_addr1_base     (cfg_desceng_addr1_base),
                .cfg_desceng_addr1_limit    (cfg_desceng_addr1_limit),

                // Control Engine Configuration (global broadcast)
                .cfg_ctrlrd_max_try         (cfg_ctrlrd_max_try),
                .tick_1us                   (tick_1us),

                // Status
                .descriptor_engine_idle (descriptor_engine_idle[ch]),
                .scheduler_idle         (scheduler_idle[ch]),
                .scheduler_state        (scheduler_state[ch]),
                .sched_error            (sched_error[ch]),

                // Descriptor AXI (per channel, to arbiter)
                .desc_ar_valid          (desc_ar_valid[ch]),
                .desc_ar_ready          (desc_ar_ready[ch]),
                .desc_ar_addr           (desc_ar_addr[ch]),
                .desc_ar_len            (desc_ar_len[ch]),
                .desc_ar_size           (desc_ar_size[ch]),
                .desc_ar_burst          (desc_ar_burst[ch]),
                .desc_ar_id             (desc_ar_id[ch]),
                .desc_ar_lock           (desc_ar_lock[ch]),
                .desc_ar_cache          (desc_ar_cache[ch]),
                .desc_ar_prot           (desc_ar_prot[ch]),
                .desc_ar_qos            (desc_ar_qos[ch]),
                .desc_ar_region         (desc_ar_region[ch]),

                .desc_r_valid           (desc_r_valid[ch]),
                .desc_r_ready           (desc_r_ready[ch]),
                .desc_r_data            (desc_r_data[ch]),
                .desc_r_resp            (desc_r_resp[ch]),
                .desc_r_last            (desc_r_last[ch]),
                .desc_r_id              (desc_r_id[ch]),

                // Control Read AXI (per channel, to ctrlrd arbiter)
                .ctrlrd_ar_valid        (ctrlrd_ar_valid[ch]),
                .ctrlrd_ar_ready        (ctrlrd_ar_ready[ch]),
                .ctrlrd_ar_addr         (ctrlrd_ar_addr[ch]),
                .ctrlrd_ar_len          (ctrlrd_ar_len[ch]),
                .ctrlrd_ar_size         (ctrlrd_ar_size[ch]),
                .ctrlrd_ar_burst        (ctrlrd_ar_burst[ch]),
                .ctrlrd_ar_id           (ctrlrd_ar_id[ch]),
                .ctrlrd_ar_lock         (ctrlrd_ar_lock[ch]),
                .ctrlrd_ar_cache        (ctrlrd_ar_cache[ch]),
                .ctrlrd_ar_prot         (ctrlrd_ar_prot[ch]),
                .ctrlrd_ar_qos          (ctrlrd_ar_qos[ch]),
                .ctrlrd_ar_region       (ctrlrd_ar_region[ch]),
                .ctrlrd_r_valid         (ctrlrd_r_valid[ch]),
                .ctrlrd_r_ready         (ctrlrd_r_ready[ch]),
                .ctrlrd_r_data          (ctrlrd_r_data[ch]),
                .ctrlrd_r_id            (ctrlrd_r_id[ch]),
                .ctrlrd_r_resp          (ctrlrd_r_resp[ch]),
                .ctrlrd_r_last          (ctrlrd_r_last[ch]),

                // Control Write AXI (per channel, to ctrlwr serializer)
                .ctrlwr_aw_valid        (ctrlwr_aw_valid[ch]),
                .ctrlwr_aw_ready        (ctrlwr_aw_ready[ch]),
                .ctrlwr_aw_addr         (ctrlwr_aw_addr[ch]),
                .ctrlwr_aw_len          (ctrlwr_aw_len[ch]),
                .ctrlwr_aw_size         (ctrlwr_aw_size[ch]),
                .ctrlwr_aw_burst        (ctrlwr_aw_burst[ch]),
                .ctrlwr_aw_id           (ctrlwr_aw_id[ch]),
                .ctrlwr_aw_lock         (ctrlwr_aw_lock[ch]),
                .ctrlwr_aw_cache        (ctrlwr_aw_cache[ch]),
                .ctrlwr_aw_prot         (ctrlwr_aw_prot[ch]),
                .ctrlwr_aw_qos          (ctrlwr_aw_qos[ch]),
                .ctrlwr_aw_region       (ctrlwr_aw_region[ch]),
                .ctrlwr_w_valid         (ctrlwr_w_valid[ch]),
                .ctrlwr_w_ready         (ctrlwr_w_ready[ch]),
                .ctrlwr_w_data          (ctrlwr_w_data[ch]),
                .ctrlwr_w_strb          (ctrlwr_w_strb[ch]),
                .ctrlwr_w_last          (ctrlwr_w_last[ch]),
                .ctrlwr_b_valid         (ctrlwr_b_valid[ch]),
                .ctrlwr_b_ready         (ctrlwr_b_ready[ch]),
                .ctrlwr_b_id            (ctrlwr_b_id[ch]),
                .ctrlwr_b_resp          (ctrlwr_b_resp[ch]),

                // Data read interface (direct passthrough - no arbitration)
                .sched_rd_valid         (sched_rd_valid[ch]),
                .sched_rd_addr          (sched_rd_addr[ch]),
                .sched_rd_beats         (sched_rd_beats[ch]),
                .sched_rd_pkt_valid     (sched_rd_pkt_valid[ch]),
                .sched_rd_pkt_ready     (sched_rd_pkt_ready[ch]),
                .sched_rd_pkt_bytes     (sched_rd_pkt_bytes[ch]),
                .sched_rd_pkt_offset    (sched_rd_pkt_offset[ch]),

                // Data write interface (direct passthrough - no arbitration)
                .sched_wr_valid         (sched_wr_valid[ch]),
                .sched_wr_ready         (sched_wr_ready[ch]),
                .sched_wr_addr          (sched_wr_addr[ch]),
                .sched_wr_beats         (sched_wr_beats[ch]),
                .sched_wr_pkt_valid     (sched_wr_pkt_valid[ch]),
                .sched_wr_pkt_ready     (sched_wr_pkt_ready[ch]),
                .sched_wr_pkt_bytes     (sched_wr_pkt_bytes[ch]),
                .sched_wr_pkt_offset    (sched_wr_pkt_offset[ch]),

                // Completion strobes (direct passthrough)
                .sched_rd_done_strobe   (sched_rd_done_strobe[ch]),
                .sched_rd_beats_done    (sched_rd_beats_done[ch]),
                .sched_wr_done_strobe   (sched_wr_done_strobe[ch]),
                .sched_wr_beats_done    (sched_wr_beats_done[ch]),
                .sched_wr_commit_strobe (sched_wr_commit_strobe[ch]),
                .sched_wr_commit_beats  (sched_wr_commit_beats[ch]),

                // Error signals (direct passthrough)
                .sched_rd_error         (sched_rd_error[ch]),
                .sched_wr_error         (sched_wr_error[ch]),

                // Monitor bus (per channel, with side-band timestamp)
                .i_mon_time             (i_mon_time),
                .mon_valid              (mon_valid_ch[ch]),
                .mon_ready              (mon_ready_ch[ch]),
                .mon_packet             (mon_packet_ch[ch]),
                .mon_timestamp          (mon_timestamp_ch[ch])
            );
        end

    //=========================================================================
    // Descriptor AXI AR Channel Arbitration
    //=========================================================================

    // Round-robin arbiter with ACK mode for proper AXI handshaking
    arbiter_round_robin #(
        .CLIENTS                (NUM_CHANNELS),
        .WAIT_GNT_ACK           (1)  // ACK mode: wait for grant acknowledgment
    ) u_desc_ar_arbiter (
        .clk                    (clk),
        .rst_n                  (rst_n),
        .block_arb              (1'b0),
        .request                (desc_ar_valid),
        .grant_ack              (desc_ar_grant_ack),
        .grant_valid            (desc_ar_grant_valid),
        .grant                  (desc_ar_grant),
        .grant_id               (desc_ar_grant_id),
        .last_grant             (/* unused */)
    );

    // Grant acknowledgment: asserted when granted client's AR request is accepted
    always_comb begin
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            desc_ar_grant_ack[ch] = desc_ar_grant_valid && desc_ar_grant[ch] && desc_ar_valid[ch] && desc_axi_int_arready;
        end
    end

    // AR channel ready: granted channel sees internal ready only when grant is valid
    always_comb begin
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            desc_ar_ready[ch] = desc_ar_grant_valid && desc_ar_grant[ch] && desc_axi_int_arready;
        end
    end

    // AR channel multiplexing: select granted channel
    always_comb begin
        desc_axi_int_arvalid = '0;
        desc_axi_int_araddr = '0;
        desc_axi_int_arlen = '0;
        desc_axi_int_arsize = '0;
        desc_axi_int_arburst = '0;
        desc_axi_int_arid = '0;
        desc_axi_int_arlock = '0;
        desc_axi_int_arcache = '0;
        desc_axi_int_arprot = '0;
        desc_axi_int_arqos = '0;
        desc_axi_int_arregion = '0;

        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            if (desc_ar_grant[ch]) begin
                desc_axi_int_arvalid = desc_ar_valid[ch];
                desc_axi_int_araddr = desc_ar_addr[ch];
                desc_axi_int_arlen = desc_ar_len[ch];
                desc_axi_int_arsize = desc_ar_size[ch];
                desc_axi_int_arburst = desc_ar_burst[ch];
                // Embed channel ID in lower bits of AXI ID for R channel demux
                desc_axi_int_arid = {{(AXI_ID_WIDTH-CHAN_WIDTH){1'b0}}, ch[CHAN_WIDTH-1:0]};
                desc_axi_int_arlock = desc_ar_lock[ch];
                desc_axi_int_arcache = desc_ar_cache[ch];
                desc_axi_int_arprot = desc_ar_prot[ch];
                desc_axi_int_arqos = desc_ar_qos[ch];
                desc_axi_int_arregion = desc_ar_region[ch];
            end
        end
    end

    //=========================================================================
    // Descriptor AXI R Channel Demultiplexing
    //=========================================================================

    // Extract channel ID from lower bits of R channel ID
    logic [CHAN_WIDTH-1:0] desc_r_channel_id;
    assign desc_r_channel_id = desc_axi_int_rid[CHAN_WIDTH-1:0];

    // R channel demultiplexing: route based on ID
    always_comb begin
        // Default: no valid to any channel
        desc_r_valid = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            desc_r_data[ch] = desc_axi_int_rdata;
            desc_r_resp[ch] = desc_axi_int_rresp;
            desc_r_last[ch] = desc_axi_int_rlast;
            desc_r_id[ch] = desc_axi_int_rid;
        end

        // Route R valid to correct channel based on ID
        if (desc_axi_int_rvalid && desc_r_channel_id < NUM_CHANNELS) begin
            desc_r_valid[desc_r_channel_id] = 1'b1;
        end
    end

    // R channel ready: OR of all channel readies (only routed channel should be ready)
    assign desc_axi_int_rready = |desc_r_ready;

    //=========================================================================
    // Control Read AXI (ctrlrd) - shared master, round-robin AR arbitration
    //=========================================================================
    // Mirrors the descriptor-fetch master: per-channel AR arbitrated onto one
    // shared 32-bit read master, channel-ID embedded in ARID, R demuxed by RID.
    arbiter_round_robin #(
        .CLIENTS      (NUM_CHANNELS),
        .WAIT_GNT_ACK (1)
    ) u_ctrlrd_ar_arbiter (
        .clk(clk), .rst_n(rst_n), .block_arb(1'b0),
        .request     (ctrlrd_ar_valid),
        .grant_ack   (ctrlrd_ar_grant_ack),
        .grant_valid (ctrlrd_ar_grant_valid),
        .grant       (ctrlrd_ar_grant),
        .grant_id    (ctrlrd_ar_grant_id),
        .last_grant  (/* unused */)
    );

    always_comb begin
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            ctrlrd_ar_grant_ack[ch] = ctrlrd_ar_grant_valid && ctrlrd_ar_grant[ch] &&
                                      ctrlrd_ar_valid[ch] && ctrlrd_axi_arready;
            ctrlrd_ar_ready[ch]     = ctrlrd_ar_grant_valid && ctrlrd_ar_grant[ch] &&
                                      ctrlrd_axi_arready;
        end
    end

    always_comb begin
        ctrlrd_axi_arvalid  = 1'b0;
        ctrlrd_axi_araddr   = '0;
        ctrlrd_axi_arlen    = '0;
        ctrlrd_axi_arsize   = '0;
        ctrlrd_axi_arburst  = '0;
        ctrlrd_axi_arid     = '0;
        ctrlrd_axi_arlock   = '0;
        ctrlrd_axi_arcache  = '0;
        ctrlrd_axi_arprot   = '0;
        ctrlrd_axi_arqos    = '0;
        ctrlrd_axi_arregion = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            if (ctrlrd_ar_grant[ch]) begin
                ctrlrd_axi_arvalid  = ctrlrd_ar_valid[ch];
                ctrlrd_axi_araddr   = ctrlrd_ar_addr[ch];
                ctrlrd_axi_arlen    = ctrlrd_ar_len[ch];
                ctrlrd_axi_arsize   = ctrlrd_ar_size[ch];
                ctrlrd_axi_arburst  = ctrlrd_ar_burst[ch];
                ctrlrd_axi_arid     = {{(AXI_ID_WIDTH-CHAN_WIDTH){1'b0}}, ch[CHAN_WIDTH-1:0]};
                ctrlrd_axi_arlock   = ctrlrd_ar_lock[ch];
                ctrlrd_axi_arcache  = ctrlrd_ar_cache[ch];
                ctrlrd_axi_arprot   = ctrlrd_ar_prot[ch];
                ctrlrd_axi_arqos    = ctrlrd_ar_qos[ch];
                ctrlrd_axi_arregion = ctrlrd_ar_region[ch];
            end
        end
    end

    logic [CHAN_WIDTH-1:0] ctrlrd_r_channel_id;
    assign ctrlrd_r_channel_id = ctrlrd_axi_rid[CHAN_WIDTH-1:0];
    always_comb begin
        ctrlrd_r_valid = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            ctrlrd_r_data[ch] = ctrlrd_axi_rdata;
            ctrlrd_r_resp[ch] = ctrlrd_axi_rresp;
            ctrlrd_r_last[ch] = ctrlrd_axi_rlast;
            ctrlrd_r_id[ch]   = ctrlrd_axi_rid;
        end
        if (ctrlrd_axi_rvalid && ctrlrd_r_channel_id < NUM_CHANNELS) begin
            ctrlrd_r_valid[ctrlrd_r_channel_id] = 1'b1;
        end
    end
    assign ctrlrd_axi_rready = |ctrlrd_r_ready;

    //=========================================================================
    // Control Write AXI (ctrlwr) - shared master, SERIALIZED across channels
    //=========================================================================
    // Round-robin picks the next channel; block_arb holds off new grants while a
    // write is in flight (r_ctrlwr_busy). One outstanding write at a time keeps
    // AW/W/B unambiguous for single-beat doorbells.
    arbiter_round_robin #(
        .CLIENTS      (NUM_CHANNELS),
        .WAIT_GNT_ACK (1)
    ) u_ctrlwr_aw_arbiter (
        .clk(clk), .rst_n(rst_n), .block_arb(r_ctrlwr_busy),
        .request     (ctrlwr_aw_valid),
        .grant_ack   (ctrlwr_aw_grant_ack),
        .grant_valid (ctrlwr_aw_grant_valid),
        .grant       (ctrlwr_aw_grant),
        .grant_id    (ctrlwr_aw_grant_id),
        .last_grant  (/* unused */)
    );

    // AW fires when the granted channel's AW is accepted (only while idle).
    logic w_ctrlwr_aw_fire;
    assign w_ctrlwr_aw_fire = !r_ctrlwr_busy && ctrlwr_aw_grant_valid &&
                              ctrlwr_aw_valid[ctrlwr_aw_grant_id] && ctrlwr_axi_awready;

    always_comb begin
        for (int ch = 0; ch < NUM_CHANNELS; ch++)
            ctrlwr_aw_grant_ack[ch] = w_ctrlwr_aw_fire && ctrlwr_aw_grant[ch];
    end

    // Serializer: latch active channel on AW accept; hold busy until B completes.
    `ALWAYS_FF_RST(clk, rst_n,
        if (`RST_ASSERTED(rst_n)) begin
            r_ctrlwr_busy      <= 1'b0;
            r_ctrlwr_active_ch <= '0;
        end else begin
            if (w_ctrlwr_aw_fire) begin
                r_ctrlwr_busy      <= 1'b1;
                r_ctrlwr_active_ch <= ctrlwr_aw_grant_id;
            end else if (r_ctrlwr_busy && ctrlwr_axi_bvalid && ctrlwr_axi_bready) begin
                r_ctrlwr_busy      <= 1'b0;
            end
        end
    )

    // AW mux: granted channel only, while idle (issuing the address phase).
    always_comb begin
        ctrlwr_axi_awvalid  = 1'b0;
        ctrlwr_axi_awaddr   = '0;
        ctrlwr_axi_awlen    = '0;
        ctrlwr_axi_awsize   = '0;
        ctrlwr_axi_awburst  = '0;
        ctrlwr_axi_awid     = '0;
        ctrlwr_axi_awlock   = '0;
        ctrlwr_axi_awcache  = '0;
        ctrlwr_axi_awprot   = '0;
        ctrlwr_axi_awqos    = '0;
        ctrlwr_axi_awregion = '0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++)
            ctrlwr_aw_ready[ch] = 1'b0;

        if (!r_ctrlwr_busy && ctrlwr_aw_grant_valid) begin
            ctrlwr_axi_awvalid  = ctrlwr_aw_valid[ctrlwr_aw_grant_id];
            ctrlwr_axi_awaddr   = ctrlwr_aw_addr[ctrlwr_aw_grant_id];
            ctrlwr_axi_awlen    = ctrlwr_aw_len[ctrlwr_aw_grant_id];
            ctrlwr_axi_awsize   = ctrlwr_aw_size[ctrlwr_aw_grant_id];
            ctrlwr_axi_awburst  = ctrlwr_aw_burst[ctrlwr_aw_grant_id];
            ctrlwr_axi_awid     = {{(AXI_ID_WIDTH-CHAN_WIDTH){1'b0}}, ctrlwr_aw_grant_id};
            ctrlwr_axi_awlock   = ctrlwr_aw_lock[ctrlwr_aw_grant_id];
            ctrlwr_axi_awcache  = ctrlwr_aw_cache[ctrlwr_aw_grant_id];
            ctrlwr_axi_awprot   = ctrlwr_aw_prot[ctrlwr_aw_grant_id];
            ctrlwr_axi_awqos    = ctrlwr_aw_qos[ctrlwr_aw_grant_id];
            ctrlwr_axi_awregion = ctrlwr_aw_region[ctrlwr_aw_grant_id];
            ctrlwr_aw_ready[ctrlwr_aw_grant_id] = ctrlwr_axi_awready;
        end
    end

    // W + B: routed to/from the active (busy) channel.
    always_comb begin
        ctrlwr_axi_wvalid = 1'b0;
        ctrlwr_axi_wdata  = '0;
        ctrlwr_axi_wstrb  = '0;
        ctrlwr_axi_wlast  = 1'b0;
        ctrlwr_axi_bready = 1'b0;
        for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
            ctrlwr_w_ready[ch] = 1'b0;
            ctrlwr_b_valid[ch] = 1'b0;
            ctrlwr_b_id[ch]    = ctrlwr_axi_bid;
            ctrlwr_b_resp[ch]  = ctrlwr_axi_bresp;
        end
        if (r_ctrlwr_busy) begin
            ctrlwr_axi_wvalid = ctrlwr_w_valid[r_ctrlwr_active_ch];
            ctrlwr_axi_wdata  = ctrlwr_w_data[r_ctrlwr_active_ch];
            ctrlwr_axi_wstrb  = ctrlwr_w_strb[r_ctrlwr_active_ch];
            ctrlwr_axi_wlast  = ctrlwr_w_last[r_ctrlwr_active_ch];
            ctrlwr_w_ready[r_ctrlwr_active_ch] = ctrlwr_axi_wready;
            ctrlwr_b_valid[r_ctrlwr_active_ch] = ctrlwr_axi_bvalid;
            ctrlwr_axi_bready = ctrlwr_b_ready[r_ctrlwr_active_ch];
        end
    end

    end else begin : g_shared
        //---------------------------------------------------------------------
        // Shared engines: one scheduler per channel, ONE descriptor engine,
        // ONE ctrlrd engine and ONE ctrlwr engine for the whole array. Each
        // engine picks among the schedulers round-robin and owns its AXI
        // master outright, so the AXI-side arbiters of the per-channel
        // structure are gone.
        //---------------------------------------------------------------------
        logic [NUM_CHANNELS-1:0]                  s_desc_valid, s_desc_ready, s_desc_error;
        logic [NUM_CHANNELS-1:0][255:0]           s_desc_packet, s_desc_ext;
        logic [NUM_CHANNELS-1:0]                  s_ctrlrd_valid, s_ctrlrd_ready;
        logic [NUM_CHANNELS-1:0]                  s_ctrlrd_error, s_ctrlrd_idle;
        logic [NUM_CHANNELS-1:0][ADDR_WIDTH-1:0]  s_ctrlrd_addr;
        logic [NUM_CHANNELS-1:0][31:0]            s_ctrlrd_data, s_ctrlrd_mask;
        logic [NUM_CHANNELS-1:0]                  s_ctrlwr_valid, s_ctrlwr_ready;
        logic [NUM_CHANNELS-1:0]                  s_ctrlwr_error, s_ctrlwr_idle;
        logic [NUM_CHANNELS-1:0][ADDR_WIDTH-1:0]  s_ctrlwr_addr;
        logic [NUM_CHANNELS-1:0][31:0]            s_ctrlwr_data;

        logic                                     s_dmon_valid, s_dmon_ready;
        ocelus_common_pkg::monitor_packet_t      s_dmon_packet;
        ocelus_common_pkg::monbus_timestamp_t    s_dmon_timestamp;

`include "scheduler_group_array_g_seq.svh"

        for (genvar ch = 0; ch < NUM_CHANNELS; ch++) begin : gen_schedulers
            logic                                   w_smon_valid, w_smon_ready;
            ocelus_common_pkg::monitor_packet_t    w_smon_packet;
            logic                                   w_smon_pass;

            scheduler_g #(
                .CHANNEL_ID             (ch),
                .NUM_CHANNELS           (NUM_CHANNELS),
                .CHAN_WIDTH             (CHAN_WIDTH),
                .ADDR_WIDTH             (ADDR_WIDTH),
                .DATA_WIDTH             (DATA_WIDTH),
                .MON_AGENT_ID           (16'(SCHED_MON_BASE_AGENT_ID + ch)),
                .MON_UNIT_ID            (8'(MON_UNIT_ID)),
                .MON_CHANNEL_ID         (9'(ch)),
                .EN_READ                (EN_READ),
                .EN_WRITE               (EN_WRITE),
                .USE_ROW_COL_MAJOR_ADDRESSING (USE_ROW_COL_MAJOR_ADDRESSING),
                .TILE_HDR               (TILE_HDR),
                .TILE_CREDITS           (TILE_CREDITS)
            ) u_scheduler (
                .clk                     (clk),
                .rst_n                   (rst_n),
                .cfg_channel_enable      (cfg_channel_enable[ch]),
                .cfg_channel_reset       (cfg_channel_reset[ch]),
                .cfg_sched_timeout_cycles(cfg_sched_timeout_cycles),
                .cfg_sched_timeout_limit (cfg_sched_timeout_limit),
                .cfg_sched_timeout_enable(cfg_sched_timeout_enable),
                .tile_adv_done           (tile_adv_done),
                .tile_dest_legal         (tile_dest_legal),
                .seq_wr_en               (g_seq_wr_en[ch]),
                .seq_wr_addr             (g_seq_wr_addr),
                .seq_wr_data             (g_seq_wr_data),
                .seq_rd_addr             (g_seq_rd_addr),
                .seq_rd_data             (g_seq_rd_data[ch]),
                .seq_attn                (g_seq_attn[ch]),
                .seq_fault               (g_seq_fault[ch]),
                .seq_alg_max             (g_seq_alg_max),
                .scheduler_idle          (scheduler_idle[ch]),
                .scheduler_state         (scheduler_state[ch]),
                .sched_error             (sched_error[ch]),
                /* verilator lint_off PINCONNECTEMPTY */
                .dbg_descriptor_error    (),
                .dbg_read_error_sticky   (),
                .dbg_write_error_sticky  (),
                .dbg_timeout_expired     (),
                /* verilator lint_on PINCONNECTEMPTY */
                .descriptor_valid        (s_desc_valid[ch]),
                .descriptor_ready        (s_desc_ready[ch]),
                .descriptor_packet       (s_desc_packet[ch]),
                .descriptor_ext_packet   (s_desc_ext[ch]),
                .descriptor_error        (s_desc_error[ch]),
                .sched_rd_valid          (sched_rd_valid[ch]),
                .sched_rd_addr           (sched_rd_addr[ch]),
                .sched_rd_beats          (sched_rd_beats[ch]),
                .sched_rd_pkt_valid      (sched_rd_pkt_valid[ch]),
                .sched_rd_pkt_ready      (sched_rd_pkt_ready[ch]),
                .sched_rd_pkt_bytes      (sched_rd_pkt_bytes[ch]),
                .sched_rd_pkt_offset     (sched_rd_pkt_offset[ch]),
                .sched_rd_pkt_tile       (sched_rd_pkt_tile[ch]),
                .sched_wr_valid          (sched_wr_valid[ch]),
                .sched_wr_ready          (sched_wr_ready[ch]),
                .sched_wr_addr           (sched_wr_addr[ch]),
                .sched_wr_beats          (sched_wr_beats[ch]),
                .sched_wr_pkt_valid      (sched_wr_pkt_valid[ch]),
                .sched_wr_pkt_ready      (sched_wr_pkt_ready[ch]),
                .sched_wr_pkt_bytes      (sched_wr_pkt_bytes[ch]),
                .sched_wr_pkt_offset     (sched_wr_pkt_offset[ch]),
                .sched_rd_done_strobe    (sched_rd_done_strobe[ch]),
                .sched_rd_beats_done     (sched_rd_beats_done[ch]),
                .sched_wr_done_strobe    (sched_wr_done_strobe[ch]),
                .sched_wr_beats_done     (sched_wr_beats_done[ch]),
                .sched_wr_commit_strobe  (sched_wr_commit_strobe[ch]),
                .sched_wr_commit_beats   (sched_wr_commit_beats[ch]),
                .sched_rd_error          (sched_rd_error[ch]),
                .sched_wr_error          (sched_wr_error[ch]),
                .ctrlrd_valid            (s_ctrlrd_valid[ch]),
                .ctrlrd_ready            (s_ctrlrd_ready[ch]),
                .ctrlrd_addr             (s_ctrlrd_addr[ch]),
                .ctrlrd_data             (s_ctrlrd_data[ch]),
                .ctrlrd_mask             (s_ctrlrd_mask[ch]),
                .ctrlrd_error            (s_ctrlrd_error[ch]),
                .ctrlrd_idle             (s_ctrlrd_idle[ch]),
                .ctrlwr_valid            (s_ctrlwr_valid[ch]),
                .ctrlwr_ready            (s_ctrlwr_ready[ch]),
                .ctrlwr_addr             (s_ctrlwr_addr[ch]),
                .ctrlwr_data             (s_ctrlwr_data[ch]),
                .ctrlwr_error            (s_ctrlwr_error[ch]),
                .ctrlwr_idle             (s_ctrlwr_idle[ch]),
                .i_mon_time              (i_mon_time),
                .mon_valid               (w_smon_valid),
                .mon_ready               (w_smon_ready),
                .mon_packet              (w_smon_packet),
                .mon_timestamp           (mon_timestamp_ch[ch])
            );

            // SCHED_CONFIG.COMPL_EN gates Completion packets (rapids ISSUE-005),
            // GEN_MON gates the stream entirely -- as scheduler_group does.
            assign w_smon_pass        = cfg_sched_compl_enable ||
                                        (ocelus_common_pkg::get_packet_type(w_smon_packet)
                                         != ocelus_common_pkg::PktTypeCompletion);
            assign mon_valid_ch[ch]   = w_smon_valid && w_smon_pass && GEN_MON;
            assign w_smon_ready       = (w_smon_pass && GEN_MON) ? mon_ready_ch[ch] : 1'b1;
            assign mon_packet_ch[ch]  = w_smon_packet;
        end

        descriptor_engine_shared #(
            .NUM_CHANNELS   (NUM_CHANNELS),
            .CHAN_WIDTH     ((CHAN_WIDTH > 0) ? CHAN_WIDTH : 1),
            .ADDR_WIDTH     (ADDR_WIDTH),
            .AXI_ID_WIDTH   (AXI_ID_WIDTH),
            .USE_ROW_COL_MAJOR_ADDRESSING (USE_ROW_COL_MAJOR_ADDRESSING),
            .MON_AGENT_BASE (16'(DESC_MON_BASE_AGENT_ID)),
            .MON_UNIT_ID    (8'(MON_UNIT_ID)),
            .INJ_EN         (TILE_HDR != 0),
            .INJ_HOLD       (TILE_CREDITS != 0)
        ) u_desc_engine (
            .clk                    (clk),
            .rst_n                  (rst_n),
            .apb_valid              (apb_valid),
            .apb_ready              (apb_ready),
            .apb_addr               (apb_addr),
            .channel_idle           (scheduler_idle),
            .descriptor_valid       (s_desc_valid),
            .descriptor_ready       (s_desc_ready),
            .descriptor_packet      (s_desc_packet),
            .descriptor_ext_packet  (s_desc_ext),
            .descriptor_error       (s_desc_error),
            /* verilator lint_off PINCONNECTEMPTY */
            .descriptor_eos         (),
            .descriptor_eol         (),
            .descriptor_eod         (),
            .descriptor_type        (),
            /* verilator lint_on PINCONNECTEMPTY */
            .ar_valid               (desc_axi_int_arvalid),
            .ar_ready               (desc_axi_int_arready),
            .ar_addr                (desc_axi_int_araddr),
            .ar_len                 (desc_axi_int_arlen),
            .ar_size                (desc_axi_int_arsize),
            .ar_burst               (desc_axi_int_arburst),
            .ar_id                  (desc_axi_int_arid),
            .ar_lock                (desc_axi_int_arlock),
            .ar_cache               (desc_axi_int_arcache),
            .ar_prot                (desc_axi_int_arprot),
            .ar_qos                 (desc_axi_int_arqos),
            .ar_region              (desc_axi_int_arregion),
            .r_valid                (desc_axi_int_rvalid),
            .r_ready                (desc_axi_int_rready),
            .r_data                 (desc_axi_int_rdata),
            .r_resp                 (desc_axi_int_rresp),
            .r_last                 (desc_axi_int_rlast),
            .r_id                   (desc_axi_int_rid),
            .cfg_prefetch_enable    (cfg_desceng_prefetch),
            .cfg_fifo_threshold     (cfg_desceng_fifo_thresh),
            .cfg_addr0_base         (cfg_desceng_addr0_base),
            .cfg_addr0_limit        (cfg_desceng_addr0_limit),
            .cfg_addr1_base         (cfg_desceng_addr1_base),
            .cfg_addr1_limit        (cfg_desceng_addr1_limit),
            .cfg_channel_reset      (cfg_channel_reset),
            .inj_valid              (desc_inj_valid),
            .inj_ch                 (desc_inj_ch),
            .inj_data               (desc_inj_data),
            .inj_ready              (desc_inj_ready),
            .inj_dropped            (desc_inj_dropped),
            .inj_dropped_clr        (desc_inj_dropped_clr),
            .descriptor_engine_idle (descriptor_engine_idle),
            .i_mon_time             (i_mon_time),
            .mon_valid              (s_dmon_valid),
            .mon_ready              (s_dmon_ready),
            .mon_packet             (s_dmon_packet),
            .mon_timestamp          (s_dmon_timestamp)
        );

        // Descriptor-engine stream: COMPL_EN and GEN_MON gating, as before
        logic w_dmon_pass;
        assign w_dmon_pass             = cfg_sched_compl_enable ||
                                         (ocelus_common_pkg::get_packet_type(s_dmon_packet)
                                          != ocelus_common_pkg::PktTypeCompletion);
        assign sh_desc_mon_valid       = s_dmon_valid && w_dmon_pass && GEN_MON;
        assign s_dmon_ready            = (w_dmon_pass && GEN_MON) ? sh_desc_mon_ready : 1'b1;
        assign sh_desc_mon_packet      = s_dmon_packet;
        assign sh_desc_mon_timestamp   = s_dmon_timestamp;

        logic w_crmon_valid, w_cwmon_valid;
        logic w_crmon_ready, w_cwmon_ready;

        ctrlrd_engine_shared #(
            .NUM_CHANNELS   (NUM_CHANNELS),
            .CHAN_WIDTH     ((CHAN_WIDTH > 0) ? CHAN_WIDTH : 1),
            .ADDR_WIDTH     (ADDR_WIDTH),
            .AXI_ID_WIDTH   (AXI_ID_WIDTH),
            .MON_AGENT_BASE (16'h0020),
            .MON_UNIT_ID    (8'(MON_UNIT_ID))
        ) u_ctrlrd_engine (
            .clk                (clk),
            .rst_n              (rst_n),
            .ctrlrd_valid       (s_ctrlrd_valid),
            .ctrlrd_ready       (s_ctrlrd_ready),
            .ctrlrd_addr        (s_ctrlrd_addr),
            .ctrlrd_data        (s_ctrlrd_data),
            .ctrlrd_mask        (s_ctrlrd_mask),
            .ctrlrd_error       (s_ctrlrd_error),
            .ctrlrd_idle        (s_ctrlrd_idle),
            .cfg_ctrlrd_max_try (cfg_ctrlrd_max_try),
            .cfg_channel_reset  (cfg_channel_reset),
            .tick_1us           (tick_1us),
            .ar_valid           (ctrlrd_axi_arvalid),
            .ar_ready           (ctrlrd_axi_arready),
            .ar_addr            (ctrlrd_axi_araddr),
            .ar_len             (ctrlrd_axi_arlen),
            .ar_size            (ctrlrd_axi_arsize),
            .ar_burst           (ctrlrd_axi_arburst),
            .ar_id              (ctrlrd_axi_arid),
            .ar_lock            (ctrlrd_axi_arlock),
            .ar_cache           (ctrlrd_axi_arcache),
            .ar_prot            (ctrlrd_axi_arprot),
            .ar_qos             (ctrlrd_axi_arqos),
            .ar_region          (ctrlrd_axi_arregion),
            .r_valid            (ctrlrd_axi_rvalid),
            .r_ready            (ctrlrd_axi_rready),
            .r_data             (ctrlrd_axi_rdata),
            .r_id               (ctrlrd_axi_rid),
            .r_resp             (ctrlrd_axi_rresp),
            .r_last             (ctrlrd_axi_rlast),
            .i_mon_time         (i_mon_time),
            .mon_valid          (w_crmon_valid),
            .mon_ready          (w_crmon_ready),
            .mon_packet         (sh_ctrlrd_mon_packet),
            .mon_timestamp      (sh_ctrlrd_mon_timestamp)
        );

        ctrlwr_engine_shared #(
            .NUM_CHANNELS   (NUM_CHANNELS),
            .CHAN_WIDTH     ((CHAN_WIDTH > 0) ? CHAN_WIDTH : 1),
            .ADDR_WIDTH     (ADDR_WIDTH),
            .AXI_ID_WIDTH   (AXI_ID_WIDTH),
            .MON_AGENT_BASE (16'h0028),
            .MON_UNIT_ID    (8'(MON_UNIT_ID))
        ) u_ctrlwr_engine (
            .clk                (clk),
            .rst_n              (rst_n),
            .ctrlwr_valid       (s_ctrlwr_valid),
            .ctrlwr_ready       (s_ctrlwr_ready),
            .ctrlwr_addr        (s_ctrlwr_addr),
            .ctrlwr_data        (s_ctrlwr_data),
            .ctrlwr_error       (s_ctrlwr_error),
            .ctrlwr_idle        (s_ctrlwr_idle),
            .cfg_channel_reset  (cfg_channel_reset),
            .aw_valid           (ctrlwr_axi_awvalid),
            .aw_ready           (ctrlwr_axi_awready),
            .aw_addr            (ctrlwr_axi_awaddr),
            .aw_len             (ctrlwr_axi_awlen),
            .aw_size            (ctrlwr_axi_awsize),
            .aw_burst           (ctrlwr_axi_awburst),
            .aw_id              (ctrlwr_axi_awid),
            .aw_lock            (ctrlwr_axi_awlock),
            .aw_cache           (ctrlwr_axi_awcache),
            .aw_prot            (ctrlwr_axi_awprot),
            .aw_qos             (ctrlwr_axi_awqos),
            .aw_region          (ctrlwr_axi_awregion),
            .w_valid            (ctrlwr_axi_wvalid),
            .w_ready            (ctrlwr_axi_wready),
            .w_data             (ctrlwr_axi_wdata),
            .w_strb             (ctrlwr_axi_wstrb),
            .w_last             (ctrlwr_axi_wlast),
            .b_valid            (ctrlwr_axi_bvalid),
            .b_ready            (ctrlwr_axi_bready),
            .b_id               (ctrlwr_axi_bid),
            .b_resp             (ctrlwr_axi_bresp),
            .i_mon_time         (i_mon_time),
            .mon_valid          (w_cwmon_valid),
            .mon_ready          (w_cwmon_ready),
            .mon_packet         (sh_ctrlwr_mon_packet),
            .mon_timestamp      (sh_ctrlwr_mon_timestamp)
        );

        // GEN_MON gates the control engines' streams (scheduler_group did)
        assign sh_ctrlrd_mon_valid = w_crmon_valid && GEN_MON;
        assign w_crmon_ready       = GEN_MON ? sh_ctrlrd_mon_ready : 1'b1;
        assign sh_ctrlwr_mon_valid = w_cwmon_valid && GEN_MON;
        assign w_cwmon_ready       = GEN_MON ? sh_ctrlwr_mon_ready : 1'b1;
    end
    endgenerate

    //=========================================================================
    // Data Read/Write Interface - Direct Passthrough (NO ARBITRATION)
    //=========================================================================
    // All signals connected directly in scheduler_group instantiations above
    // Engines handle arbitration internally

    //=========================================================================
    // Descriptor AXI Master Monitor
    //=========================================================================

    // axi_monitor_lite (rtl/amba/monitors TASK-001): the lite monitor on the same
    // taps. No debug, address-range checker, ID/address filters or per-event masks
    // -- those cfg inputs stay on this module's ports for the register block but
    // drive nothing here. Drop-and-count instead of block_ready. The lite has no
    // cfg-conflict check either; the status bit reads 0.
    assign cfg_sts_desc_mon_conflict_error = 1'b0;

    //-------------------------------------------------------------------------
    // Descriptor-AXI perf window (DAXMON_PERF_* CSRs).
    //
    // The full monitor computed this window inside itself; the lite does not
    // (it has no perf cone), and the first lite swap left these outputs
    // undriven, so DAXMON_PERF_STATUS.WIN_ACTIVE read 0 with RUN set and
    // top' test_rapids_top_perf_window failed. The window is
    // now the same always-on meter the top uses for RDMON/WRMON
    // (rapids_top.sv u_rd_bus_meter): axi_bus_meter on the R channel
    // for the four cycle buckets, plus beat/byte/burst accumulators. Window
    // control is DAXMON_PERF_CTRL.RUN: clear on its rising edge, count while
    // high, freeze while low. WIN_ACTIVE is RUN itself; WINDOW_CYCLES is
    // LIVE-only per the RDL ("valid only while WIN_ACTIVE=1"), so it reads 0
    // after close while the buckets hold. Deliberately NOT gated by
    // USE_AXI_MONITORS, for the reason the top gives: over-gating the cheap
    // meters was a real cause of zero perf readings on monitors-off builds.
    //-------------------------------------------------------------------------
    logic        r_desc_perf_run_d;
    logic        w_desc_perf_start;
    logic [31:0] r_desc_win_cycles;
    logic [31:0] r_desc_beats;
    logic [63:0] r_desc_bytes;
    logic [31:0] r_desc_bursts;

    assign w_desc_perf_start = cfg_desc_mon_perf_run && !r_desc_perf_run_d;

    `ALWAYS_FF_RST(clk, rst_n,
        if (`RST_ASSERTED(rst_n)) begin
            r_desc_perf_run_d <= 1'b0;
            r_desc_win_cycles <= '0;
            r_desc_beats      <= '0;
            r_desc_bytes      <= '0;
            r_desc_bursts     <= '0;
        end else begin
            r_desc_perf_run_d <= cfg_desc_mon_perf_run;
            if (w_desc_perf_start) begin
                r_desc_win_cycles <= '0;
                r_desc_beats      <= '0;
                r_desc_bytes      <= '0;
                r_desc_bursts     <= '0;
            end else if (cfg_desc_mon_perf_run) begin
                r_desc_win_cycles <= r_desc_win_cycles + 32'd1;
                if (desc_axi_int_rvalid && desc_axi_int_rready) begin
                    r_desc_beats <= r_desc_beats + 32'd1;
                    // Descriptor fetches are fixed 256-bit beats (the port
                    // width above), so a beat is 32 bytes.
                    r_desc_bytes <= r_desc_bytes + 64'd32;
                end
                if (desc_axi_int_arvalid && desc_axi_int_arready) begin
                    r_desc_bursts <= r_desc_bursts + 32'd1;
                end
            end
        end
    )

    /* verilator lint_off PINCONNECTEMPTY */
    axi_bus_meter #(.NUM_CHANNELS(1)) u_desc_bus_meter (
        .aclk               (clk),
        .aresetn            (rst_n),
        .i_clear            (w_desc_perf_start),
        .i_freeze           (~cfg_desc_mon_perf_run),
        .i_valid            (desc_axi_int_rvalid),
        .i_ready            (desc_axi_int_rready),
        .i_channel_id       (1'b0),
        .i_channel_valid    (1'b0),   // one shared descriptor port: aggregate only
        .o_agg_productive   (sts_desc_mon_prod_cycles),
        .o_agg_backpressure (sts_desc_mon_bp_cycles),
        .o_agg_starvation   (sts_desc_mon_starv_cycles),
        .o_agg_idle         (sts_desc_mon_idle_cycles),
        .o_ch_productive    (),
        .o_ch_backpressure  (),
        .o_ch_starvation    (),
        .o_ch_idle          (),
        .o_ch_overflow      ()
    );
    /* verilator lint_on PINCONNECTEMPTY */

    assign sts_desc_mon_win_active  = cfg_desc_mon_perf_run;
    assign sts_desc_mon_win_cycles  = cfg_desc_mon_perf_run ? r_desc_win_cycles : 32'd0;
    assign sts_desc_mon_beat_count  = r_desc_beats;
    assign sts_desc_mon_byte_count  = r_desc_bytes;
    assign sts_desc_mon_burst_count = r_desc_bursts;

    axi4_master_rd_monlite #(
        .AXI_ID_WIDTH     (AXI_ID_WIDTH),
        .AXI_ADDR_WIDTH   (ADDR_WIDTH),
        .AXI_DATA_WIDTH   (256),  // FIXED 256-bit for descriptor size
        .AXI_USER_WIDTH   (1),
        .UNIT_ID          (8'(MON_UNIT_ID)),
        .AGENT_ID         (16'(DESC_AXI_MON_AGENT_ID)),
        .MAX_TRANSACTIONS (MON_MAX_TRANSACTIONS),
        .USE_MONITOR      (USE_AXI_MONITORS == 1)
    ) u_desc_axi_monitor (
        .aclk                 (clk),
        .aresetn              (rst_n),
        .fub_axi_arid         (desc_axi_int_arid),
        .fub_axi_araddr       (desc_axi_int_araddr),
        .fub_axi_arlen        (desc_axi_int_arlen),
        .fub_axi_arsize       (desc_axi_int_arsize),
        .fub_axi_arburst      (desc_axi_int_arburst),
        .fub_axi_arlock       (desc_axi_int_arlock),
        .fub_axi_arcache      (desc_axi_int_arcache),
        .fub_axi_arprot       (desc_axi_int_arprot),
        .fub_axi_arqos        (desc_axi_int_arqos),
        .fub_axi_arregion     (desc_axi_int_arregion),
        .fub_axi_aruser       (1'b0),
        .fub_axi_arvalid      (desc_axi_int_arvalid),
        .fub_axi_arready      (desc_axi_int_arready),
        .fub_axi_rid          (desc_axi_int_rid),
        .fub_axi_rdata        (desc_axi_int_rdata),
        .fub_axi_rresp        (desc_axi_int_rresp),
        .fub_axi_rlast        (desc_axi_int_rlast),
        .fub_axi_ruser        (),  // Unused, leave floating
        .fub_axi_rvalid       (desc_axi_int_rvalid),
        .fub_axi_rready       (desc_axi_int_rready),
        .m_axi_arid           (desc_axi_arid),
        .m_axi_araddr         (desc_axi_araddr),
        .m_axi_arlen          (desc_axi_arlen),
        .m_axi_arsize         (desc_axi_arsize),
        .m_axi_arburst        (desc_axi_arburst),
        .m_axi_arlock         (desc_axi_arlock),
        .m_axi_arcache        (desc_axi_arcache),
        .m_axi_arprot         (desc_axi_arprot),
        .m_axi_arqos          (desc_axi_arqos),
        .m_axi_arregion       (desc_axi_arregion),
        .m_axi_aruser         (),  // Unused
        .m_axi_arvalid        (desc_axi_arvalid),
        .m_axi_arready        (desc_axi_arready),
        .m_axi_rid            (desc_axi_rid),
        .m_axi_rdata          (desc_axi_rdata),
        .m_axi_rresp          (desc_axi_rresp),
        .m_axi_rlast          (desc_axi_rlast),
        .m_axi_ruser          (1'b0),  // Input, tie to constant
        .m_axi_rvalid         (desc_axi_rvalid),
        .m_axi_rready         (desc_axi_rready),
        .cfg_monitor_enable   (cfg_desc_mon_enable),
        .cfg_error_enable     (cfg_desc_mon_err_enable),
        .cfg_timeout_enable   (cfg_desc_mon_timeout_enable),
        // the monitor's timeout is 16 bits: CSR values above 0xFFFF are not representable
        .cfg_timeout_cycles   (cfg_desc_mon_timeout_cycles[15:0]),
        .cfg_freq_sel         (4'b0000),
        .cfg_axi_pkt_mask     (cfg_desc_mon_pkt_mask),
        .cfg_latency_threshold (cfg_desc_mon_latency_thresh),
        .cfg_addr_check_enable (1'b0),
        .cfg_addr_match_enable (1'b0),
        .cfg_addr_range_enable ('0),
        .cfg_addr_range_low    ('0),
        .cfg_addr_range_high   ('0),
        .cam_clear            (1'b0),
        .cfg_compl_enable     (1'b0),
        .cfg_threshold_enable (1'b0),
        .i_mon_time           (i_mon_time),
        .monbus_valid         (desc_axi_mon_valid),
        .monbus_ready         (desc_axi_mon_ready),
        .monbus_packet        (desc_axi_mon_packet),
        .monbus_timestamp     (desc_axi_mon_timestamp),
        .busy                 (cfg_sts_desc_mon_busy),
        .active_transactions  (cfg_sts_desc_mon_active_txns),
        .error_count          (cfg_sts_desc_mon_error_count),
        .transaction_count    (cfg_sts_desc_mon_txn_count),
        .dropped_count        (),  // lite: events lost to monbus backpressure (counted, reported as EVENT_DROPPED)
        .refused_count        ()  // lite: commands that found no free table entry
    );

    //=========================================================================
    // Monitor Bus Aggregation
    //=========================================================================

    // Combine the channel streams, the descriptor AXI monitor and (shared
    // engines only) the three engines' streams. Each source contributes packet
    // + side-band timestamp. One complete always_comb per build so no index is
    // ever out of range.
    generate
    if (SHARED_ENGINES == 0) begin : g_agg_per_channel
        always_comb begin
            for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
                monbus_valid_all[ch]     = mon_valid_ch[ch];
                mon_ready_ch[ch]         = monbus_ready_all[ch];
                monbus_packet_all[ch]    = mon_packet_ch[ch];
                monbus_timestamp_all[ch] = mon_timestamp_ch[ch];
            end
            monbus_valid_all[NUM_CHANNELS]     = desc_axi_mon_valid;
            desc_axi_mon_ready                 = monbus_ready_all[NUM_CHANNELS];
            monbus_packet_all[NUM_CHANNELS]    = desc_axi_mon_packet;
            monbus_timestamp_all[NUM_CHANNELS] = desc_axi_mon_timestamp;
        end
        assign sh_desc_mon_ready   = 1'b1;
        assign sh_ctrlrd_mon_ready = 1'b1;
        assign sh_ctrlwr_mon_ready = 1'b1;
    end else begin : g_agg_shared
        always_comb begin
            for (int ch = 0; ch < NUM_CHANNELS; ch++) begin
                monbus_valid_all[ch]     = mon_valid_ch[ch];
                mon_ready_ch[ch]         = monbus_ready_all[ch];
                monbus_packet_all[ch]    = mon_packet_ch[ch];
                monbus_timestamp_all[ch] = mon_timestamp_ch[ch];
            end
            monbus_valid_all[NUM_CHANNELS]       = desc_axi_mon_valid;
            desc_axi_mon_ready                   = monbus_ready_all[NUM_CHANNELS];
            monbus_packet_all[NUM_CHANNELS]      = desc_axi_mon_packet;
            monbus_timestamp_all[NUM_CHANNELS]   = desc_axi_mon_timestamp;
            monbus_valid_all[NUM_CHANNELS+1]     = sh_desc_mon_valid;
            sh_desc_mon_ready                    = monbus_ready_all[NUM_CHANNELS+1];
            monbus_packet_all[NUM_CHANNELS+1]    = sh_desc_mon_packet;
            monbus_timestamp_all[NUM_CHANNELS+1] = sh_desc_mon_timestamp;
            monbus_valid_all[NUM_CHANNELS+2]     = sh_ctrlrd_mon_valid;
            sh_ctrlrd_mon_ready                  = monbus_ready_all[NUM_CHANNELS+2];
            monbus_packet_all[NUM_CHANNELS+2]    = sh_ctrlrd_mon_packet;
            monbus_timestamp_all[NUM_CHANNELS+2] = sh_ctrlrd_mon_timestamp;
            monbus_valid_all[NUM_CHANNELS+3]     = sh_ctrlwr_mon_valid;
            sh_ctrlwr_mon_ready                  = monbus_ready_all[NUM_CHANNELS+3];
            monbus_packet_all[NUM_CHANNELS+3]    = sh_ctrlwr_mon_packet;
            monbus_timestamp_all[NUM_CHANNELS+3] = sh_ctrlwr_mon_timestamp;
        end
    end
    endgenerate

    // Aggregate all monitor sources (packet + side-band timestamp)
    monbus_arbiter #(
        .CLIENTS                (MONBUS_SOURCES),
        .INPUT_SKID_ENABLE      (1),
        .OUTPUT_SKID_ENABLE     (1),
        .INPUT_SKID_DEPTH       (2),
        .OUTPUT_SKID_DEPTH      (2)
    ) u_monbus_aggregator (
        .axi_aclk               (clk),
        .axi_aresetn            (rst_n),
        .block_arb              (1'b0),
        .monbus_valid_in        (monbus_valid_all),
        .monbus_ready_in        (monbus_ready_all),
        .monbus_packet_in       (monbus_packet_all),
        .monbus_timestamp_in    (monbus_timestamp_all),
        .monbus_valid           (mon_valid),
        .monbus_ready           (mon_ready),
        .monbus_packet          (mon_packet),
        .monbus_timestamp       (mon_timestamp),
        .grant_valid            (/* unused */),
        .grant                  (/* unused */),
        .grant_id               (/* unused */),
        .last_grant             (/* unused */)
    );

endmodule : scheduler_group_array_g
